namespace MoreSpace {
class LargeHit {public Entry Entry;public string Blocked;}
class LargeProgress {public List<LargeHit> Hits;public long Visited;public int Skipped;}
static class LargeScanner {
 public static List<LargeHit> Read(string[] roots,CancellationToken token,Action<LargeProgress> publish,long minimum=100L*1024*1024){var hits=new List<LargeHit>();var batch=new List<LargeHit>();var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);long visited=0;int skipped=0;var watch=Stopwatch.StartNew();
  foreach(var root in roots){token.ThrowIfCancellationRequested();try{if(!Engine.NoLinks(root)){skipped++;continue;}}catch{skipped++;continue;}var pending=new Stack<string>();pending.Push(root);while(pending.Count>0){token.ThrowIfCancellationRequested();string dir=pending.Pop();try{if(!seen.Add(Path.GetFullPath(dir))||(File.GetAttributes(dir)&FileAttributes.ReparsePoint)!=0)continue;foreach(var info in new DirectoryInfo(dir).EnumerateFileSystemInfos()){token.ThrowIfCancellationRequested();try{var attributes=info.Attributes;if((attributes&FileAttributes.ReparsePoint)!=0){skipped++;continue;}if((attributes&FileAttributes.Directory)!=0)pending.Push(info.FullName);else{visited++;var file=(FileInfo)info;if(file.Length>=minimum){var hit=new LargeHit{Entry=new Entry{Path=file.FullName,Size=file.Length,Modified=file.LastWriteTimeUtc}};try{ChartFileRules.Validate(hit.Entry,dir);}catch(Exception ex){hit.Blocked=ex.Message;}hits.Add(hit);batch.Add(hit);}}}catch(IOException){skipped++;}catch(UnauthorizedAccessException){skipped++;}if(watch.ElapsedMilliseconds>=500){publish(new LargeProgress{Hits=batch,Visited=visited,Skipped=skipped});batch=new List<LargeHit>();watch.Restart();}}}catch(IOException){skipped++;}catch(UnauthorizedAccessException){skipped++;}}}
  publish(new LargeProgress{Hits=batch,Visited=visited,Skipped=skipped});return hits.OrderByDescending(h=>h.Entry.Size).ToList();
 }
}
class RecentLargeScans {
 class Snapshot { public List<LargeHit> Hits; public Stopwatch Age=Stopwatch.StartNew(); }
 readonly Dictionary<string,Snapshot> completed=new Dictionary<string,Snapshot>(StringComparer.OrdinalIgnoreCase);
 public void Clear(){completed.Clear();}
 public async Task<List<LargeHit>> Read(string root,bool refresh,CancellationToken token,Action<LargeProgress> progress,Action reused){
  token.ThrowIfCancellationRequested();
  Snapshot snapshot;
  if(!refresh&&completed.TryGetValue(root,out snapshot)&&snapshot.Age.Elapsed<TimeSpan.FromMinutes(2)){
   reused();
   return snapshot.Hits;
  }
  var hits=await Task.Run(()=>LargeScanner.Read(new[]{root},token,progress));
  token.ThrowIfCancellationRequested();
  completed[root]=new Snapshot{Hits=hits};
  return hits;
 }
}
partial class MainWindow {
 readonly RecentLargeScans recentLarge=new RecentLargeScans();
 ComboBox drivePicker=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=115}; bool largeStarted,largeScanning,selectIncoming,insights;Button deleteLarge,stopLarge;Label largeSummary=new Label();readonly Dictionary<string,string> largeBlocked=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);
 void SetupLargeFiles(){var page=Page("Arquivos grandes","A busca começa ao abrir esta tela: arquivos de 100 MB ou mais nos discos locais, do maior para o menor. Itens protegidos ficam somente para consulta.");var bar=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false,AutoScroll=true};scanLarge=Btn("Buscar novamente",async delegate{insights=false;await SearchLarge(true);});deleteLarge=Btn("Excluir marcados…",async delegate{await DeleteLarge();});stopLarge=Btn("Cancelar busca",delegate{if(largeScanning&&cts!=null)cts.Cancel();});stopLarge.Enabled=false;drivePicker.Items.Add("Todos os discos");foreach(var drive in DriveInfo.GetDrives())if(drive.DriveType==DriveType.Fixed&&drive.IsReady)drivePicker.Items.Add(drive.Name);drivePicker.SelectedIndex=0;drivePicker.SelectedIndexChanged+=async delegate{RenderCards();largeStarted=false;if(largeScanning){cts.Cancel();return;}if(!busy)await SearchLarge();};bar.Controls.Add(drivePicker);bar.Controls.Add(scanLarge);bar.Controls.Add(deleteLarge);bar.Controls.Add(Btn("Mostrar no Explorer",delegate{Reveal(large);}));bar.Controls.Add(stopLarge);bar.Controls.Add(Btn("Selecionar todos",delegate{if(busy&&!largeScanning)return;selectIncoming=largeScanning;large.BeginUpdate();try{foreach(ListViewItem item in large.Items)if(!largeBlocked.ContainsKey(((Entry)item.Tag).Path))item.Checked=true;}finally{large.EndUpdate();}status.Text=large.CheckedItems.Count+" selecionados • "+largeBlocked.Count+" protegidos";}));bar.Controls.Add(Btn("Reavaliar bloqueio",delegate{if(busy||large.SelectedItems.Count==0)return;var row=large.SelectedItems[0];var file=(Entry)row.Tag;try{string folder=Path.GetDirectoryName(file.Path);ChartFileRules.Validate(file,folder,true);var attributes=File.GetAttributes(file.Path);if((attributes&FileAttributes.ReadOnly)!=0){if(MessageBox.Show(this,(english?"Remove read-only protection from this file?":"Remover o atributo somente leitura deste arquivo?")+"\r\n"+file.Path,Text,MessageBoxButtons.YesNo,MessageBoxIcon.Question,MessageBoxDefaultButton.Button2)!=DialogResult.Yes)return;File.SetAttributes(file.Path,attributes&~FileAttributes.ReadOnly);}ChartFileRules.Validate(file,folder);recentLarge.Clear();largeBlocked.Remove(file.Path);row.ForeColor=AppTheme.Text;row.ToolTipText="";row.Checked=true;}catch(Exception ex){MessageBox.Show(this,ex.Message,"Arquivo protegido");}}));large.SizeChanged+=delegate{large.Columns[3].Width=Math.Max(240,large.ClientSize.Width-large.Columns[0].Width-large.Columns[1].Width-large.Columns[2].Width);};page.Controls.Add(bar,0,1);large.CheckBoxes=true;large.ShowItemToolTips=true;page.Controls.Add(large,0,2);largeSummary.Dock=DockStyle.Fill;page.Controls.Add(largeSummary,0,3);large.DoubleClick+=delegate{Reveal(large);};large.ItemCheck+=delegate(object sender,ItemCheckEventArgs e){if((busy&&!largeScanning)||largeBlocked.ContainsKey(((Entry)large.Items[e.Index].Tag).Path))e.NewValue=e.CurrentValue;};}
 async void EnsureLargeScan(){if(!demoMode&&!busy&&!largeStarted&&tabs.SelectedTab.Text=="Arquivos grandes")await SearchLarge();}
 void AddLargeRows(IEnumerable<LargeHit> hits){large.BeginUpdate();foreach(var hit in hits){var e=hit.Entry;var row=new ListViewItem(new[]{Path.GetFileName(e.Path),Engine.Bytes(e.Size),e.Modified.ToLocalTime().ToString("g"),e.Path});row.Tag=e;if(hit.Blocked!=null){largeBlocked[e.Path]=hit.Blocked;row.ForeColor=Color.Gray;row.ToolTipText=hit.Blocked;}large.Items.Add(row);if(selectIncoming&&hit.Blocked==null)row.Checked=true;}large.EndUpdate();}
 async Task SearchLarge(bool refresh=false){int reused=0;var elapsed=Stopwatch.StartNew();if(busy||demoMode)return;largeStarted=true;largeScanning=true;selectIncoming=false;Busy(true);deleteLarge.Enabled=false;stopLarge.Enabled=true;cts=new CancellationTokenSource();large.Items.Clear();largeBlocked.Clear();largeSummary.Text="Buscando nos discos locais… Os resultados aparecem durante a leitura.";
  try{var roots=DriveInfo.GetDrives().Where(d=>d.DriveType==DriveType.Fixed&&d.IsReady).Select(d=>d.RootDirectory.FullName).ToArray();if(drivePicker.SelectedIndex>0)roots=new[]{(string)drivePicker.SelectedItem};var token=cts.Token;var counts=new Dictionary<string,LargeProgress>();var tasks=roots.Select(root=>{var progress=new Progress<LargeProgress>(p=>{if(!largeScanning||token.IsCancellationRequested)return;counts[root]=p;if(!insights)AddLargeRows(p.Hits);largeSummary.Text=counts.Values.Sum(x=>x.Visited).ToString("N0")+" arquivos lidos • "+large.Items.Count+" grandes • "+counts.Values.Sum(x=>x.Skipped)+" ignorados (resultados parciais)";});return recentLarge.Read(root,refresh,token,p=>((IProgress<LargeProgress>)progress).Report(p),()=>reused++);}).ToArray();var groups=await Task.WhenAll(tasks);var result=groups.SelectMany(g=>g).OrderByDescending(h=>h.Entry.Size).ToList();if(insights)result=result.Where(h=>h.Blocked==null).Take(25).ToList();var marked=new HashSet<string>(large.CheckedItems.Cast<ListViewItem>().Select(i=>((Entry)i.Tag).Path),StringComparer.OrdinalIgnoreCase);large.Items.Clear();largeBlocked.Clear();selectIncoming=false;AddLargeRows(result);foreach(ListViewItem item in large.Items)if(marked.Contains(((Entry)item.Tag).Path))item.Checked=true;largeSummary.Text=(insights?"Insights • até 25 candidatos por tamanho • ":"")+result.Count+" arquivos de 100 MB ou mais • ordenados do maior para o menor • marque para excluir.";status.Text="Busca concluída em "+elapsed.Elapsed.TotalSeconds.ToString("N1")+" s."+(reused==0?"":" Índice recente de "+reused+" unidade(s). Buscar novamente atualiza os dados.");
  }catch(OperationCanceledException){largeSummary.Text="Busca cancelada: resultados parciais preservados. Use Buscar novamente para completar.";}catch(Exception ex){largeSummary.Text="Busca incompleta: "+ex.Message;Log(ex.ToString());}finally{largeScanning=false;cts.Dispose();cts=null;Busy(false);deleteLarge.Enabled=true;stopLarge.Enabled=false;if(!largeStarted)EnsureLargeScan();}
 }
 async Task DeleteLarge(){if(busy)return;var selected=large.CheckedItems.Cast<ListViewItem>().Select(i=>(Entry)i.Tag).ToList();if(selected.Count==0){MessageBox.Show(this,"Marque os arquivos que deseja excluir.");return;}Busy(true);deleteLarge.Enabled=false;cancel.Enabled=false;try{using(var dialog=new ChartFileDialog(null,selected,true)){if(dialog.ShowDialog(this)!=DialogResult.OK)return;var confirmed=dialog.Selection;bool permanent=dialog.Permanent;var before=SavingsStore.Snapshot();long bytes=0;var removed=new HashSet<string>();var messages=new List<string>();await Task.Run(()=>{foreach(var e in confirmed)try{ChartFileRules.Validate(e,Path.GetDirectoryName(e.Path));FileRemoval.Delete(e.Path,permanent);removed.Add(e.Path);bytes+=e.Size;messages.Add("EXCLUÍDO ARQUIVO GRANDE "+e.Path);}catch(Exception ex){messages.Add("PRESERVADO "+e.Path+": "+ex.Message);}});foreach(var message in messages)Log(message);foreach(var row in large.Items.Cast<ListViewItem>().ToArray())if(removed.Contains(((Entry)row.Tag).Path))large.Items.Remove(row);if(removed.Count>0)RecordSavings(permanent?"Arquivos grandes":"Via Lixeira (grandes)",removed.Count,permanent?(long?)bytes:null,before);RefreshOverview();largeSummary.Text=removed.Count+" processados • "+Engine.Bytes(bytes)+" lógicos • "+(confirmed.Count-removed.Count)+" preservados/falhas.";MessageBox.Show(this,largeSummary.Text+"\r\nDetalhes em Atividade.","Resultado");}}finally{Busy(false);deleteLarge.Enabled=true;}}
}
static class LargeChecks {
 public static int Run(){string root=Path.Combine(Path.GetTempPath(),"MoreSpace-Large-"+Guid.NewGuid().ToString("N"));try{Directory.CreateDirectory(root);File.WriteAllBytes(Path.Combine(root,"small"),new byte[5]);File.WriteAllBytes(Path.Combine(root,"medium"),new byte[20]);File.WriteAllBytes(Path.Combine(root,"big"),new byte[30]);int published=0;var result=LargeScanner.Read(new[]{root,root},CancellationToken.None,p=>published+=p.Hits.Count,10);if(result.Count!=2||published!=2||result[0].Entry.Size!=30)return 91;var c=new CancellationTokenSource();c.Cancel();try{LargeScanner.Read(new[]{root},c.Token,p=>{});return 92;}catch(OperationCanceledException){}return 0;}catch{return 93;}finally{if(Directory.Exists(root))Directory.Delete(root,true);}}
}
}
